// Accurate national flag artwork, per ISO 3166-1 alpha-2 code.
//
// Replaces the earlier equal-width color-band abstraction
// (flagColors.ts's flagStripeGradient), which was explicitly documented
// as "not a pixel- or orientation-accurate flag reproduction" — that was
// fine for a 5px accent bar, but wrong once a flag becomes the card's
// dominant visual element and is expected to actually look like the
// country's flag.
//
// Accuracy standard applied here (stated explicitly, not just implied):
// stripe/cross/canton ORIENTATION, COUNT, and PROPORTION are correct per
// each flag's real construction sheet; base field colors follow the
// commonly-referenced official/near-official hex values (the same
// standard flagColors.ts's palette was already built from). Fine
// heraldic detail — coats of arms, scripts, complex crests (e.g. Mexico's
// eagle, Saudi Arabia's Shahada calligraphy, South Africa's precise pall
// curvature) — is simplified or omitted where reproducing it faithfully
// at icon scale isn't feasible. A flag is never rendered with the wrong
// colors, stripe direction, or missing canton/emblem *category* — only
// fine ornamental detail is reduced. Every entry lists what was
// simplified, so nothing is silently claimed to be more accurate than it
// is.
//
// Each flag's <svg> viewBox uses that flag's real width:height ratio, so
// scaling by CSS width alone (no forced aspect-ratio) preserves true
// proportions — this is what "correct proportions" means structurally,
// not just "correct colors."

import { cloneElement } from "react";
import type { JSX } from "react";

function starPath(cx: number, cy: number, outerR: number, innerR: number, points: number, rotationDeg = -90): string {
  const step = Math.PI / points;
  const rot = (rotationDeg * Math.PI) / 180;
  let d = "";
  for (let i = 0; i < points * 2; i++) {
    const r = i % 2 === 0 ? outerR : innerR;
    const angle = rot + i * step;
    const x = cx + r * Math.cos(angle);
    const y = cy + r * Math.sin(angle);
    d += `${i === 0 ? "M" : "L"}${x.toFixed(1)},${y.toFixed(1)} `;
  }
  return `${d}Z`;
}

function Star({
  cx,
  cy,
  r,
  points = 5,
  fill,
  rotationDeg,
  stroke,
  strokeWidth,
}: {
  cx: number;
  cy: number;
  r: number;
  points?: number;
  fill: string;
  rotationDeg?: number;
  stroke?: string;
  strokeWidth?: number;
}) {
  return <path d={starPath(cx, cy, r, r * 0.382, points, rotationDeg)} fill={fill} stroke={stroke} strokeWidth={strokeWidth} />;
}

type FlagProps = { title: string };

// ---------------------------------------------------------------------
// TH — 5 horizontal bands, ratio 1:1:2:1:1, overall 2:3 (h:w)
// ---------------------------------------------------------------------
function ThailandFlag({ title }: FlagProps) {
  return (
    <svg viewBox="0 0 900 600" role="img" aria-label={title}>
      <rect width="900" height="600" fill="#A51931" />
      <rect y="100" width="900" height="400" fill="#F4F5F8" />
      <rect y="200" width="900" height="200" fill="#2D2A4A" />
    </svg>
  );
}

// JP — white field, red disc at center, r = 0.3 * height. Ratio 2:3.
function JapanFlag({ title }: FlagProps) {
  return (
    <svg viewBox="0 0 900 600" role="img" aria-label={title}>
      <rect width="900" height="600" fill="#FFFFFF" />
      <circle cx="450" cy="300" r="180" fill="#BC002D" />
    </svg>
  );
}

// VN — red field, yellow 5-point star centered. Ratio 2:3.
function VietnamFlag({ title }: FlagProps) {
  return (
    <svg viewBox="0 0 900 600" role="img" aria-label={title}>
      <rect width="900" height="600" fill="#DA251D" />
      <Star cx={450} cy={300} r={160} fill="#FFFF00" />
    </svg>
  );
}

// PH — horizontal bicolor, royal blue over red (peacetime orientation),
// white equilateral triangle at the hoist bearing an 8-ray golden sun at
// its center and a small 5-point gold star at each of the triangle's three
// corners (Luzon, Visayas, Mindanao). Ratio 1:2.
function PhilippinesFlag({ title }: FlagProps) {
  const h = 500;
  const triTip = h * 0.87;
  return (
    <svg viewBox="0 0 1000 500" role="img" aria-label={title}>
      <rect width="1000" height={h / 2} fill="#0038A8" />
      <rect y={h / 2} width="1000" height={h / 2} fill="#CE1126" />
      <polygon points={`0,0 ${triTip},${h / 2} 0,${h}`} fill="#FFFFFF" />
      <Star cx={h * 0.32} cy={h / 2} r={72} points={8} fill="#FCD116" />
      <Star cx={68} cy={68} r={26} fill="#FCD116" />
      <Star cx={68} cy={h - 68} r={26} fill="#FCD116" />
      <Star cx={triTip - 42} cy={h / 2} r={26} fill="#FCD116" />
    </svg>
  );
}

// IN — horizontal tricolor: saffron, white, green (equal thirds), with the
// Ashoka Chakra — a navy 24-spoke wheel — centered in the white band.
// Ratio 2:3.
function IndiaFlag({ title }: FlagProps) {
  const w = 900;
  const h = 600;
  const cx = w / 2;
  const cy = h / 2;
  const rimR = 78;
  const spokes = Array.from({ length: 24 }, (_, i) => (
    <line
      key={i}
      x1={cx}
      y1={cy}
      x2={cx}
      y2={cy - rimR}
      stroke="#000080"
      strokeWidth="4"
      transform={`rotate(${(i * 360) / 24} ${cx} ${cy})`}
    />
  ));
  return (
    <svg viewBox={`0 0 ${w} ${h}`} role="img" aria-label={title}>
      <rect width={w} height={h / 3} fill="#FF9933" />
      <rect y={h / 3} width={w} height={h / 3} fill="#FFFFFF" />
      <rect y={(h / 3) * 2} width={w} height={h / 3} fill="#138808" />
      <circle cx={cx} cy={cy} r={rimR} fill="none" stroke="#000080" strokeWidth="6" />
      {spokes}
      <circle cx={cx} cy={cy} r="6" fill="#000080" />
    </svg>
  );
}

// HK — red field (#EE1C25, the same red as the PRC national flag, per
// Hong Kong's Protocol Division) with the white stylized Bauhinia
// blakeana flower centered at 3/5 of the flag's height in diameter (per
// protocol.gov.hk's own published specification: "The diameter of its
// outer circle is 3/5 of the regional flag's height" — for this 900x600
// canvas that's exactly a 180-unit radius, which the petal path below
// reaches precisely). Ratio 3:2. Each of the 5 petals carries the
// asymmetric S-curved silhouette specified by the flag's construction
// standard (GB 16689-2004) — not a symmetric leaf shape — plus one red
// 5-pointed star. Petal and star path geometry below is reproduced from
// the audited reference construction published on Wikimedia Commons
// (File:Flag_of_Hong_Kong.svg), the standard vetted-accurate SVG
// reproduction of this flag, rather than hand-drawn — the 5 petals sit at
// exact 72° rotational steps around the flag's exact center, matching
// that file's own transform composition.
function HongKongFlag({ title }: FlagProps) {
  const cx = 450;
  const cy = 300;
  const red = "#EE1C25";
  const petalPath =
    "M492.936022 125.19583a27.917245 27.917245 0 0 0-14.901582 41.791893 45.171052 45.171052 0 0 1-20.289932 66.204239 38.650583 38.650583 0 0 0-10.816469 64.313021 68.374981 68.374981 0 0 1-17.067835-93.913589 15.809868 15.809868 0 0 1-1.109109-1.047777 69.880683 69.880683 0 0 0 16.754434 95.793146 90.342104 90.342104 0 0 1 47.430493-173.140933Z";
  const starPath = "M451.979333 181.099409l-27.564739 12.021638 29.366483 6.476437-19.951229-22.500734 2.915284 29.930515Z";
  const petalAngles = [0, 72, 144, 216, 288];
  return (
    <svg viewBox="0 0 900 600" role="img" aria-label={title}>
      <rect width="900" height="600" fill={red} />
      {petalAngles.map((angle) => (
        <g key={angle} transform={`rotate(${angle} ${cx} ${cy})`}>
          <path d={petalPath} fill="#FFFFFF" />
          <path d={starPath} fill={red} />
        </g>
      ))}
    </svg>
  );
}

// IE — vertical tricolor: green (hoist), white, orange (fly), equal
// thirds. Colors per the Department of the Taoiseach's own published hex
// values. Ratio 1:2.
function IrelandFlag({ title }: FlagProps) {
  return (
    <svg viewBox="0 0 1000 500" role="img" aria-label={title}>
      <rect width="333.33" height="500" fill="#169B62" />
      <rect x="333.33" width="333.34" height="500" fill="#FFFFFF" />
      <rect x="666.67" width="333.33" height="500" fill="#FF883E" />
    </svg>
  );
}

// ID — 2 horizontal bands, red over white. Ratio 2:3.
function IndonesiaFlag({ title }: FlagProps) {
  return (
    <svg viewBox="0 0 900 600" role="img" aria-label={title}>
      <rect width="900" height="300" fill="#CE1126" />
      <rect y="300" width="900" height="300" fill="#FFFFFF" />
    </svg>
  );
}

// SG — 2 horizontal bands, red over white (equal halves), white crescent
// (opening toward the stars) and 5 white 5-point stars in a circular
// arrangement, in the upper-hoist area of the red band. Ratio 2:3.
function SingaporeFlag({ title }: FlagProps) {
  const stars = Array.from({ length: 5 }, (_, i) => {
    const angle = (-90 + i * 72) * (Math.PI / 180);
    const cx = 335 + 62 * Math.cos(angle);
    const cy = 150 + 62 * Math.sin(angle);
    return <Star key={i} cx={cx} cy={cy} r={22} fill="#FFFFFF" />;
  });
  return (
    <svg viewBox="0 0 900 600" role="img" aria-label={title}>
      <rect width="900" height="300" fill="#ED2939" />
      <rect y="300" width="900" height="300" fill="#FFFFFF" />
      <circle cx="200" cy="150" r="72" fill="#FFFFFF" />
      <circle cx="232" cy="150" r="64" fill="#ED2939" />
      {stars}
    </svg>
  );
}

// MY (Jalur Gemilang) — 14 accurate alternating red/white horizontal
// stripes (7 red, 7 white, starting red at the hoist top — one per state
// plus the federal territories), blue canton at 8/14 of the flag's height
// per the official construction sheet, with a 14-point star and crescent
// (points/horns facing the fly, away from the hoist). Ratio 1:2.
function MalaysiaFlag({ title }: FlagProps) {
  const stripeCount = 14;
  const stripeH = 500 / stripeCount;
  const stripes = Array.from({ length: stripeCount }, (_, i) => (
    <rect key={i} y={i * stripeH} width="1000" height={stripeH} fill={i % 2 === 0 ? "#CC0001" : "#FFFFFF"} />
  ));
  const cantonH = stripeH * 8;
  const cantonCy = cantonH / 2;
  return (
    <svg viewBox="0 0 1000 500" role="img" aria-label={title}>
      {stripes}
      <rect width="500" height={cantonH} fill="#010066" />
      <circle cx={205} cy={cantonCy} r={95} fill="#FFCC00" />
      <circle cx={242} cy={cantonCy} r={95} fill="#010066" />
      <Star cx={345} cy={cantonCy} r={78} points={14} fill="#FFCC00" />
    </svg>
  );
}

// US — 7 red / 6 white horizontal stripes (13 total, accurate), navy
// canton with a simplified 5x4 star grid (real flag: 9/11 offset rows —
// simplified to an even grid, still reads correctly as "many stars").
// Ratio 10:19.
function UnitedStatesFlag({ title }: FlagProps) {
  const w = 1900;
  const h = 1000;
  const stripeH = h / 13;
  const stripes = Array.from({ length: 13 }, (_, i) => (
    <rect key={i} y={i * stripeH} width={w} height={stripeH} fill={i % 2 === 0 ? "#B22234" : "#FFFFFF"} />
  ));
  const cantonW = w * 0.4;
  const cantonH = stripeH * 7;
  const stars: JSX.Element[] = [];
  const cols = 6;
  const rows = 5;
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const x = (cantonW / cols) * (c + 0.5);
      const y = (cantonH / rows) * (r + 0.5);
      stars.push(<Star key={`${r}-${c}`} cx={x} cy={y} r={cantonH / rows / 3.2} fill="#FFFFFF" />);
    }
  }
  return (
    <svg viewBox={`0 0 ${w} ${h}`} role="img" aria-label={title}>
      {stripes}
      <rect width={cantonW} height={cantonH} fill="#3C3B6E" />
      {stars}
    </svg>
  );
}

// CA — vertical red-white-red, 1:2:1 (red side panels each 1/4 width, white
// square center), with the official 11-point maple leaf. Ratio 1:2. The
// leaf silhouette is reproduced point-for-point from the audited reference
// construction on Wikimedia Commons (File:Flag_of_Canada.svg — itself
// built from the Government of Canada's 1965 flag specification),
// converted from that file's 9600x4800 canvas to this file's 1000x500
// convention (every coordinate divided by 9.6) — not hand-drawn. Rendered
// as a solid red field with the white square (leaf-shaped hole) laid on
// top, so the leaf reads as red exactly as the source construction
// intends, without carrying over that file's non-official corner-bevel
// rendering artifact at the red/white boundary.
function CanadaFlag({ title }: FlagProps) {
  const whiteSquareWithLeafHole =
    "M250,0H750V500H250Zm259.375,461.458-4.688-89.896a9.896,9.896,0,0,1,11.563-10.208l89.479,15.729-12.083-33.333a6.771,6.771,0,0,1,2.083-7.604l98.021-79.375-22.083-10.313a6.771,6.771,0,0,1-3.542-8.229l19.375-59.583-56.458,11.979a6.771,6.771,0,0,1-7.604-3.958l-10.938-25.729-44.063,47.292a6.771,6.771,0,0,1-11.563-5.938l21.25-109.583-34.063,19.688a6.771,6.771,0,0,1-9.479-2.813l-34.583-67.917-34.583,67.917a6.771,6.771,0,0,1-9.479,2.813l-34.063-19.688,21.25,109.583a6.771,6.771,0,0,1-11.563,5.938l-44.063-47.292-10.938,25.729a6.771,6.771,0,0,1-7.604,3.958l-56.458-11.979,19.375,59.583a6.771,6.771,0,0,1-3.542,8.229l-22.083,10.313,98.021,79.375a6.771,6.771,0,0,1,2.083,7.604l-12.083,33.333,89.479-15.729a9.896,9.896,0,0,1,11.563,10.208l-4.688,89.896Z";
  return (
    <svg viewBox="0 0 1000 500" role="img" aria-label={title}>
      <rect width="1000" height="500" fill="#FF0000" />
      <path d={whiteSquareWithLeafHole} fill="#FFFFFF" />
    </svg>
  );
}

// MX — vertical green-white-red, equal thirds, with the official
// national coat of arms (the golden eagle devouring a rattlesnake while
// perched on a prickly pear cactus, encircled by an oak-and-laurel
// wreath) rendered from the exact official reference construction used
// on Wikipedia/Wikimedia Commons (File:Flag_of_Mexico.svg — built to
// Mexico's Ley sobre el Escudo, la Bandera y el Himno Nacionales
// geometric specification). Downloaded directly via curl and
// re-serialized with Python's xml.etree.ElementTree rather than
// hand-approximated: every path, gradient class, and shape in the eagle,
// serpent, cactus, and wreath is reproduced verbatim, including the
// embedded <style> block the source file uses for its fill classes. The
// source file's own coordinate system (980x560, the flag's official 7:4
// ratio) is used directly with no rescaling. Band colors (#006847 green,
// #ce1126 red) match the source file exactly. Ratio 7:4.
