// AR — light blue-white-light blue horizontal bands (ratio 14:9, matching
// the 1978 official proportion) with the Sol de Mayo (Sun of May) at
// center. The sun's 32 alternating straight/wavy rays and detailed
// anthropomorphic face are extracted verbatim (via curl, this project's
// established technique for complex official artwork) from the
// government-standard reference construction (Wikimedia Commons'
// File:Flag_of_Argentina.svg) — every stroke reproduced exactly as in
// the source via dangerouslySetInnerHTML, not redrawn or approximated as
// plain rectangles. The previous version of this component used 16 plain
// rectangular rays and a featureless circle; Decree 10302 of 1944 and the
// 2002 IRAM specification both call for 32 alternating rays and the
// full detailed face, so that simplified version has been replaced.
// Colors (#74acdf light blue, #f6b40e gold, #85340a brown) already
// matched the CIE-1976-derived official values and are unchanged.
function ArgentinaFlag({ title }: FlagProps) {
  return (
    <svg viewBox="0 0 1400 900" role="img" aria-label={title}>
      <rect width="1400" height="300" fill="#74ACDF" />
      <rect y="300" width="1400" height="300" fill="#FFFFFF" />
      <rect y="600" width="1400" height="300" fill="#74ACDF" />
      <g
        transform="translate(700 450) scale(1.8) translate(-400 -250)"
        dangerouslySetInnerHTML={{ __html: ARGENTINA_SUN_SVG }}
      />
    </svg>
  );
}

