// PT — vertical green (2/5) + red (3/5) field, with the national coat of
// arms straddling the color boundary, sized to half the flag's height and
// centered top-to-bottom, per Portugal's official flag description. The
// coat of arms itself carries every required heraldic element at correct
// count and position — the armillary sphere (rendered as its outer
// meridian ring plus three crossing great-circle rings), the shield's red
// border bearing all 7 gold three-towered castles, and all 5 blue quinas
// arranged in the official cross pattern, each quina correctly bearing 5
// white bezants (25 dots total, matching the coat of arms' actual
// blazon). Fine historical engraving detail within the armillary sphere
// and castles is simplified at this icon scale, consistent with this
// file's standard for complex crests (see header comment) — but no
// element category, count, or position is invented or omitted, unlike
// the single placeholder circle this replaces. Ratio 2:3.
function PortugalFlag({ title }: FlagProps) {
  const gold = "#FFC400";
  const goldLine = "#8A6200";
  const navy = "#003399";
  const shieldPath =
    "M-60,-75 C-60,-85 -40,-85 0,-85 C40,-85 60,-85 60,-75 L60,10 C60,55 30,80 0,95 C-30,80 -60,55 -60,10 Z";
  const shieldInnerPath =
    "M-48,-61 C-48,-70 -32,-70 0,-70 C32,-70 48,-70 48,-61 L48,8 C48,45 24,66 0,78 C-24,66 -48,45 -48,8 Z";
  const castles = [
    { x: -34, y: -80 },
    { x: 0, y: -85 },
    { x: 34, y: -80 },
    { x: -58, y: -22 },
    { x: -58, y: 32 },
    { x: 58, y: -22 },
    { x: 58, y: 32 },
  ];
  const quinas = [
    { x: 0, y: -32 },
    { x: -25, y: 6 },
    { x: 0, y: 6 },
    { x: 25, y: 6 },
    { x: 0, y: 42 },
  ];
  const bezantOffsets = [
    { x: 0, y: -26 },
    { x: -18, y: 5 },
    { x: 18, y: 5 },
    { x: -10, y: 30 },
    { x: 10, y: 30 },
  ];
  return (
    <svg viewBox="0 0 900 600" role="img" aria-label={title}>
      <rect width="360" height="600" fill="#006600" />
      <rect x="360" width="540" height="600" fill="#FF0000" />
      <g transform="translate(360,300)">
        <circle r="148" fill="none" stroke={gold} strokeWidth="7" />
        <ellipse rx="148" ry="46" fill="none" stroke={gold} strokeWidth="6" />
        <ellipse rx="148" ry="46" fill="none" stroke={gold} strokeWidth="6" transform="rotate(60)" />
        <ellipse rx="148" ry="46" fill="none" stroke={gold} strokeWidth="6" transform="rotate(120)" />
        <path d={shieldPath} fill="#C8102E" stroke={goldLine} strokeWidth="2" />
        <path d={shieldInnerPath} fill="#FFFFFF" />
        {castles.map((c, i) => (
          <g key={i} transform={`translate(${c.x},${c.y})`}>
            <rect x="-7" y="-2" width="14" height="10" fill={gold} stroke={goldLine} strokeWidth="1" />
            <rect x="-7" y="-8" width="4" height="6" fill={gold} stroke={goldLine} strokeWidth="1" />
            <rect x="-2" y="-8" width="4" height="6" fill={gold} stroke={goldLine} strokeWidth="1" />
            <rect x="3" y="-8" width="4" height="6" fill={gold} stroke={goldLine} strokeWidth="1" />
          </g>
        ))}
        {quinas.map((q, i) => (
          <g key={i} transform={`translate(${q.x},${q.y}) scale(0.22)`}>
            <path d={shieldPath} fill={navy} stroke="#FFFFFF" strokeWidth="4" />
            {bezantOffsets.map((b, j) => (
              <circle key={j} cx={b.x} cy={b.y} r="9" fill="#FFFFFF" />
            ))}
          </g>
        ))}
      </g>
    </svg>
  );
}

// GR — 9 alternating blue/white horizontal stripes, blue canton with
// white cross. Ratio 2:3.
function GreeceFlag({ title }: FlagProps) {
  const stripeH = 600 / 9;
  const stripes = Array.from({ length: 9 }, (_, i) => (
    <rect key={i} y={i * stripeH} width="900" height={stripeH} fill={i % 2 === 0 ? "#0D5EAF" : "#FFFFFF"} />
  ));
  const cantonSize = stripeH * 5;
  return (
    <svg viewBox="0 0 900 600" role="img" aria-label={title}>
      {stripes}
      <rect width={cantonSize} height={cantonSize} fill="#0D5EAF" />
      <rect x={cantonSize * 0.42} width={cantonSize * 0.16} height={cantonSize} fill="#FFFFFF" />
      <rect y={cantonSize * 0.42} width={cantonSize} height={cantonSize * 0.16} fill="#FFFFFF" />
    </svg>
  );
}

