function SaudiArabiaFlag({ title }: FlagProps) {
  return (
    <svg viewBox="0 0 900 600" role="img" aria-label={title}>
      <rect width="900" height="600" fill="#005430" />
      <g transform="scale(.375)" dangerouslySetInnerHTML={{ __html: SAUDI_SHAHADA_SWORD_SVG }} />
    </svg>
  );
}

// QA — maroon field with white hoist band, 9-point serrated (zigzag)
// separator. Ratio 11:28 (Qatar's flag is notably elongated).
function QatarFlag({ title }: FlagProps) {
  const zig: string[] = [];
  const teeth = 9;
  const bandX = 280;
  const toothW = 60;
  const h = 440;
  const step = h / teeth;
  let d = `M0,0 L${bandX},0 `;
  for (let i = 0; i < teeth; i++) {
    const yTop = i * step;
    const yMid = yTop + step / 2;
    const yBot = yTop + step;
    d += `L${bandX - toothW},${yMid} L${bandX},${yBot} `;
  }
  d += `L0,${h} Z`;
  zig.push(d);
  return (
    <svg viewBox="0 0 1120 440" role="img" aria-label={title}>
      <rect width="1120" height="440" fill="#8D1B3D" />
      <path d={zig[0]} fill="#FFFFFF" />
    </svg>
  );
}

// JO — horizontal black-white-green stripes, red triangle from hoist
// bearing a white 7-point star. Ratio 1:2.
function JordanFlag({ title }: FlagProps) {
  return (
    <svg viewBox="0 0 1000 500" role="img" aria-label={title}>
      <rect width="1000" height="167" fill="#000000" />
      <rect y="167" width="1000" height="166" fill="#FFFFFF" />
      <rect y="333" width="1000" height="167" fill="#007A3D" />
      <polygon points="0,0 480,250 0,500" fill="#CE1126" />
      <Star cx={180} cy={250} r={55} points={7} fill="#FFFFFF" />
    </svg>
  );
}

// ZA — precise pall (Y-shape) construction, scaled 10x from the official
// geometric proportions used in the government-standard reference artwork
// (Wikimedia Commons File:Flag_of_South_Africa.svg's own construction),
// re-colored to the government-published hex values rather than that
// file's own slightly different rounding. Ratio 2:3.
function SouthAfricaFlag({ title }: FlagProps) {
  return (
    <svg viewBox="0 0 900 600" role="img" aria-label={title}>
      <defs>
        <clipPath id="za-hoist-triangle">
          <path d="M0 0L450 300L0 600Z" />
        </clipPath>
      </defs>
      <path fill="#DE3831" d="M0 0H900V300H450Z" />
      <path fill="#002395" d="M0 600H900V300H450Z" />
      <g fill="none">
        <path stroke="#FFFFFF" strokeWidth="200" d="M900 300H450L0 0V600L450 300" />
        <path fill="#000000" stroke="#FFB612" strokeWidth="200" clipPath="url(#za-hoist-triangle)" d="M0 0L450 300L0 600" />
        <path stroke="#007A4D" strokeWidth="120" d="M0 0L450 300H900M0 600L450 300" />
      </g>
    </svg>
  );
}

// MA — red field, green pentagram outline centered. Ratio 2:3.
function MoroccoFlag({ title }: FlagProps) {
  return (
    <svg viewBox="0 0 900 600" role="img" aria-label={title}>
      <rect width="900" height="600" fill="#C1272D" />
      <path
        d={starPath(450, 300, 110, 42, 5)}
        fill="none"
        stroke="#006233"
        strokeWidth="12"
      />
    </svg>
  );
}

// KE — horizontal black-red-green, thin white fimbriations, Maasai
// shield/spears omitted (simplified circle stands in for the emblem
// position). Ratio 2:3.
function KenyaFlag({ title }: FlagProps) {
  return (
    <svg viewBox="0 0 900 600" role="img" aria-label={title}>
      <rect width="900" height="600" fill="#FFFFFF" />
      <rect y="60" width="900" height="160" fill="#000000" />
      <rect y="220" width="900" height="20" fill="#FFFFFF" />
      <rect y="240" width="900" height="120" fill="#BB0000" />
      <rect y="360" width="900" height="20" fill="#FFFFFF" />
      <rect y="380" width="900" height="160" fill="#006600" />
      <circle cx="450" cy="300" r="70" fill="#FFFFFF" stroke="#000000" strokeWidth="6" />
    </svg>
  );
}

// NG — vertical tricolor, green-white-green, no emblem. Ratio 1:2, per
// the Flag and Coat-of-Arms Ordinance of 1960. Green is the value most
// specifically cited against Nigeria's flag (as opposed to a generic
// websafe-green guess), hex #008751.
function NigeriaFlag({ title }: FlagProps) {
  return (
    <svg viewBox="0 0 900 600" role="img" aria-label={title}>
      <rect width="300" height="600" fill="#008751" />
      <rect x="300" width="300" height="600" fill="#FFFFFF" />
      <rect x="600" width="300" height="600" fill="#008751" />
    </svg>
  );
}

// LK — maroon field, gold-bordered lion holding a sword with four gold
// bo-leaves in the crimson panel's corners, plus green and saffron
// vertical stripes at the hoist. This is the most geometrically complex
// flag built in this project after Saudi Arabia's calligraphy. The lion,
// sword, and bo-leaf paths below are extracted verbatim (via curl +
// Python's xml.etree.ElementTree, per this project's established
// technique for complex official artwork) from the government-standard
// reference construction (Wikimedia Commons' File:Flag_of_Sri_Lanka.svg),
// not redrawn or approximated — every stroke reproduced exactly as in
// the source. Colors are re-mapped from that file's own slightly
// different rounding to the values published in Sri Lanka Standard
// SLS 1:2020 (the government flag specification): gold/lion #FDB813,
// crimson field #A20000, orange stripe #FF8000, green stripe #007A3D.
