// AU — dark blue field (#00008B), Union Jack canton (upper-left quarter,
// same construction as the UK flag above), a 7-pointed Commonwealth Star
// in the lower hoist, and the 5-star Southern Cross in the fly (4
// 7-pointed stars — Alpha, Beta, Gamma, Delta Crucis — plus the smaller
// 5-pointed Epsilon Crucis). Ratio 1:2. Star positions, radii, and the
// official 4:9 inner-to-outer point ratio (not this file's usual
// starPath default) are reproduced from the audited reference
// construction on Wikimedia Commons (File:Flag_of_Australia.svg),
// converted from its 10080x5040 canvas to this file's 1000x500
// convention (divide every source coordinate by 10.08) — not
// hand-drawn or approximated.
function AustraliaFlag({ title }: FlagProps) {
  const starInnerRatio = 4 / 9;
  const star7Radius = 35.714;
  const southernCross7 = [
    { cx: 750, cy: 416.667 }, // Alpha Crucis
    { cx: 625, cy: 218.75 }, // Beta Crucis
    { cx: 750, cy: 83.333 }, // Gamma Crucis
    { cx: 861.111, cy: 185.417 }, // Delta Crucis
  ];
  return (
    <svg viewBox="0 0 1000 500" role="img" aria-label={title}>
      <rect width="1000" height="500" fill="#00008B" />
      <g transform="scale(0.5)">
        <path d="M0 0L1000 500M1000 0L0 500" stroke="#FFFFFF" strokeWidth="100" />
        <path d="M0 0L1000 500M1000 0L0 500" stroke="#FF0000" strokeWidth="34" />
        <rect y="200" width="1000" height="100" fill="#FFFFFF" />
        <rect x="450" width="100" height="500" fill="#FFFFFF" />
        <rect y="220" width="1000" height="60" fill="#FF0000" />
        <rect x="470" width="60" height="500" fill="#FF0000" />
      </g>
      <path d={starPath(250, 375, 75, 75 * starInnerRatio, 7)} fill="#FFFFFF" />
      {southernCross7.map((s, i) => (
        <path key={i} d={starPath(s.cx, s.cy, star7Radius, star7Radius * starInnerRatio, 7)} fill="#FFFFFF" />
      ))}
      <path d={starPath(800, 270.833, 20.833, 20.833 * starInnerRatio, 5)} fill="#FFFFFF" />
    </svg>
  );
}

// NZ — blue field (#012169, the same Pantone 280 used for the Union
// Flag and its derivatives), Union Jack canton, and the 4-star Southern
// Cross built from the exact geometric construction specified in the
// New Zealand Gazette (27 June 1902) — not estimated. Per that spec, on
// a flag of hoist H: the long limb's two stars (top/Gacrux, bottom/
// Acrux) sit on a vertical line midway between the Union Jack and the
// fly's outer edge, 36/60·H apart, centered on the flag's vertical
// midpoint; the short limb's two stars (left/Becrux, right/Delta Crucis)
// sit on a line crossing the vertical at 82° (not 90° — the Southern
// Cross on this flag is deliberately not a true right-angle cross),
// 12/60·H before the top star along the vertical, at 12/60·H (right
// star) and 14/60·H (left star) along that crossing line. Star sizes
// (point-to-point) are 6/60·H (top), 7/60·H (bottom), 5/60·H (right,
// nearest the fly edge), 6/60·H (left, nearest the Union Jack), each
// with a 1/120·H white border. Ratio 1:2.
function NewZealandFlag({ title }: FlagProps) {
  const blue = "#012169";
  const red = "#C8102E";
  const borderWidth = 500 / 120;
  return (
    <svg viewBox="0 0 1000 500" role="img" aria-label={title}>
      <rect width="1000" height="500" fill={blue} />
      <g transform="scale(0.5)">
        <path d="M0 0L1000 500M1000 0L0 500" stroke="#FFFFFF" strokeWidth="100" />
        <path d="M0 0L1000 500M1000 0L0 500" stroke={red} strokeWidth="34" />
        <rect y="200" width="1000" height="100" fill="#FFFFFF" />
        <rect x="450" width="100" height="500" fill="#FFFFFF" />
        <rect y="220" width="1000" height="60" fill={red} />
        <rect x="470" width="60" height="500" fill={red} />
      </g>
      <Star cx={750} cy={100} r={25} fill={red} stroke="#FFFFFF" strokeWidth={borderWidth} />
      <Star cx={849.027} cy={186.083} r={20.833} fill={red} stroke="#FFFFFF" strokeWidth={borderWidth} />
      <Star cx={634.469} cy={216.237} r={25} fill={red} stroke="#FFFFFF" strokeWidth={borderWidth} />
      <Star cx={750} cy={400} r={29.167} fill={red} stroke="#FFFFFF" strokeWidth={borderWidth} />
    </svg>
  );
}

// BE — vertical black-yellow-red, equal thirds, at Belgium's official
// constitutional ratio of 13:15 (height:width) — a near-square flag,
// not the 2:3 ratio commonly (but unofficially) sold commercially. Colors
// per the Official Guide to Belgian Protocol: black #000000, yellow
// #FDDA24, red #EF3340.
function BelgiumFlag({ title }: FlagProps) {
  return (
    <svg viewBox="0 0 1500 1300" role="img" aria-label={title}>
      <rect width="500" height="1300" fill="#000000" />
      <rect x="500" width="500" height="1300" fill="#FDDA24" />
      <rect x="1000" width="500" height="1300" fill="#EF3340" />
    </svg>
  );
}

// SE — yellow Nordic cross on a blue field, per the Act on the Swedish
// Flag (1982) and government ordinance 1983:826, which defines the grid
// as 5:2:9 horizontal divisions and 4:2:4 vertical divisions (overall
// ratio 5:8, height:width). Colors per the official NCS/Pantone
// conversion: blue #005293, yellow #FFCD00.
function SwedenFlag({ title }: FlagProps) {
  return (
    <svg viewBox="0 0 1600 1000" role="img" aria-label={title}>
      <rect width="1600" height="1000" fill="#005293" />
      <rect x="500" width="200" height="1000" fill="#FFCD00" />
      <rect y="400" width="1600" height="200" fill="#FFCD00" />
    </svg>
  );
}

// DK — red field, plain (unfimbriated) white Nordic cross offset to the
// hoist, per the 1748 Danish flag regulation still in force. Rendered at
// the flag's own official 28:37 ratio (900x681) rather than this
// codebase's usual 900x600, since Dannebrog's proportions are notably
// closer to square than most flags here. Red is the value most
// consistently cited against Denmark's flag specification (Pantone
// 186C, hex #C60C30).
function DenmarkFlag({ title }: FlagProps) {
  return (
    <svg viewBox="0 0 900 681" role="img" aria-label={title}>
      <rect width="900" height="681" fill="#C60C30" />
      <rect x="292" width="146" height="681" fill="#FFFFFF" />
      <rect y="267" width="900" height="146" fill="#FFFFFF" />
    </svg>
  );
}

// TR — white crescent and five-pointed star on a red field, per Turkish
// Flag Law No. 2994 (1936), which fixes the flag's geometry as exact
// ratios of the flag's width (G): crescent outer diameter 1/2 G, inner
// circle diameter 2/5 G, star circle diameter 1/4 G. Rather than
// approximating these ratios by eye, the path data below is taken
// directly from the official reference construction used on Wikipedia/
// Wikimedia Commons (File:Flag_of_Turkey.svg), which encodes the law's
// exact geometry as two SVG paths — a self-intersecting even-odd-fill
// path for the crescent (two offset circular arcs), and a point-to-point
// path for the five-pointed star — on the flag's official 2:3 ratio
// (viewBox width 90000, height 60000). Color is the standard reference
// red, #e30a17.
function TurkeyFlag({ title }: FlagProps) {
  return (
    <svg viewBox="0 -30000 90000 60000" role="img" aria-label={title}>
      <path fill="#e30a17" d="m0-30000h90000v60000H0z" />
      <path
        fill="#fff"
        d="m41750 0 13568-4408-8386 11541V-7133l8386 11541zm925 8021a15000 15000 0 1 1 0-16042 12000 12000 0 1 0 0 16042z"
      />
    </svg>
  );
}

// CL — equal white (top) and red (bottom) horizontal bands, with a blue
// square canton (matching the white band's height) in the top-left corner
// bearing a white five-pointed star. Per Law 2597 (1912) and Supreme
// Decree No. 5805 (1927): white #FFFFFF, red #DA291C, blue #0032A0, ratio
// 3:2. The star's point construction is taken directly from the official
// reference used on Wikipedia/Wikimedia Commons (File:Flag_of_Chile.svg)
// — a precise five-fold rotational construction, not a hand-estimated
// polygon — to guarantee exact point proportions.
const CHILE_STAR_SVG = `<g id="b"><path id="a" d="M0-75V0h37.5" transform="rotate(18 0 -75)" /><use xlink:href="#a" transform="scale(-1 1)" /></g><use xlink:href="#b" transform="rotate(72)" /><use xlink:href="#b" transform="rotate(144)" /><use xlink:href="#b" transform="rotate(216)" /><use xlink:href="#b" transform="rotate(288)" />`;

function ChileFlag({ title }: FlagProps) {
  return (
    <svg viewBox="0 0 900 600" role="img" aria-label={title}>
      <rect width="900" height="600" fill="#FFFFFF" />
      <rect y="300" width="900" height="300" fill="#DA291C" />
      <rect width="300" height="300" fill="#0032A0" />
      <g fill="#FFFFFF" transform="translate(150 150)" dangerouslySetInnerHTML={{ __html: CHILE_STAR_SVG }} />
    </svg>
  );
}

// CH — white couped cross on a square red field, per the Federal Coats of
// Arms Protection Act (in force since 2017): 1:1 (square) flag ratio,
// cross-to-field size ratio 5:8, each arm's length:width ratio 7:6, red
// #FF0000. Rather than hand-derive these ratios into pixel coordinates,
// the cross path is taken directly from the official reference
// construction used on Wikipedia/Wikimedia Commons
// (File:Flag_of_Switzerland.svg, on a 32x32 grid), scaled ×25 to an
// 800x800 canvas — the scaling preserves the source's exact integer
// coordinates (and therefore its exact ratios) with no rounding drift.
function SwitzerlandFlag({ title }: FlagProps) {
  return (
    <svg viewBox="0 0 800 800" role="img" aria-label={title}>
      <rect width="800" height="800" fill="#FF0000" />
      <path
        fill="#FFFFFF"
        d="m325 150h150v175h175v150h-175v175h-150v-175h-175v-150h175z"
      />
    </svg>
  );
}

// NL — horizontal red-white-blue, equal thirds. Per the 1937 Royal
// Decree (refined 1958): bright vermilion red #AE1C28, white, cobalt
// blue #21468B — deliberately not the darker "Nassau blue" sometimes
// mistakenly used (that shade belongs to the Dutch Royal Standard, not
// the national flag). Ratio 2:3.
function NetherlandsFlag({ title }: FlagProps) {
  return (
    <svg viewBox="0 0 900 600" role="img" aria-label={title}>
      <rect width="900" height="200" fill="#AE1C28" />
      <rect y="200" width="900" height="200" fill="#FFFFFF" />
      <rect y="400" width="900" height="200" fill="#21468B" />
    </svg>
  );
}

const FLAGS: Record<string, (props: FlagProps) => JSX.Element> = {
  TH: ThailandFlag,
  JP: JapanFlag,
  VN: VietnamFlag,
  PH: PhilippinesFlag,
  IN: IndiaFlag,
  HK: HongKongFlag,
  IE: IrelandFlag,
  ID: IndonesiaFlag,
  SG: SingaporeFlag,
  MY: MalaysiaFlag,
  US: UnitedStatesFlag,
  CA: CanadaFlag,
  MX: MexicoFlag,
  BR: BrazilFlag,
  AR: ArgentinaFlag,
  PE: PeruFlag,
  ES: SpainFlag,
  IT: ItalyFlag,
  FR: FranceFlag,
  RO: RomaniaFlag,
  HU: HungaryFlag,
  AT: AustriaFlag,
  PL: PolandFlag,
  BE: BelgiumFlag,
  SE: SwedenFlag,
  DK: DenmarkFlag,
  TR: TurkeyFlag,
  CL: ChileFlag,
  CH: SwitzerlandFlag,
  NL: NetherlandsFlag,
  PT: PortugalFlag,
  GR: GreeceFlag,
  DE: GermanyFlag,
  GB: UnitedKingdomFlag,
  HR: CroatiaFlag,
  IS: IcelandFlag,
  NO: NorwayFlag,
  AE: UnitedArabEmiratesFlag,
  SA: SaudiArabiaFlag,
  QA: QatarFlag,
  JO: JordanFlag,
  ZA: SouthAfricaFlag,
  MA: MoroccoFlag,
  KE: KenyaFlag,
  NG: NigeriaFlag,
  LK: SriLankaFlag,
  AU: AustraliaFlag,
  NZ: NewZealandFlag,
};

// Fallback for any ISO code without a verified flag entry yet — a plain
// neutral field, never a guessed color pattern.
function FallbackFlag({ title }: FlagProps) {
  return (
    <svg viewBox="0 0 900 600" role="img" aria-label={title}>
      <rect width="900" height="600" fill="var(--surface)" />
      <rect width="900" height="600" fill="none" stroke="var(--border)" strokeWidth="4" />
    </svg>
  );
}

export function hasVerifiedFlag(isoCode: string): boolean {
  return isoCode.toUpperCase() in FLAGS;
}

// `style` is applied directly to the rendered <svg> root (via cloneElement),
// not just to a wrapping <span> — setting an explicit height with width
// "auto" only reliably preserves each flag's true aspect ratio when it
// lands on the replaced element itself. A wrapper-only height constraint
// left the scaling behavior ambiguous across browsers, which is what
// originally produced an oversized flag banner.
export function FlagIcon({ isoCode, title, className, style }: { isoCode: string; title: string; className?: string; style?: React.CSSProperties }) {
  const Component = FLAGS[isoCode.toUpperCase()] ?? FallbackFlag;
  const svgElement = Component({ title });
  return (
    <span className={className} style={{ display: "inline-block", lineHeight: 0 }}>
      {cloneElement(svgElement, { style: { display: "block", ...style } })}
    </span>
  );
}
